import numpy as np

with open('train.json') as f:
    train = json.load(f)

# Let's inspect all 9 train people with 3A requests, plus H09 (which has fdec at t=45, and ct available up to t=56!)
for pid, rows in sorted(train.items()):
    fdec = None
    for i in range(1, len(rows)):
        if rows[i]['watts'] < rows[i-1]['watts']:
            fdec = i
            break
    if fdec is None:
        continue
    print(f"=== {pid}: fdec_idx={fdec} (t={rows[fdec]['time_min']}), age={rows[0]['age']}, mass={rows[0]['mass']}, height={rows[0]['height']}, w0={rows[0]['watts']}->{rows[fdec]['watts']} ===")
    pts = []
    for i in range(fdec, len(rows) - 15):
        ct_now = rows[i]['core_temp']
        ct_fut = rows[i+15]['core_temp']
        pts.append((rows[i]['time_min'], ct_now, ct_fut, rows[i]['hr'], rows[i]['skin_temp'], rows[i]['watts']))
    for p in pts[::max(1, len(pts)//6)] + ([pts[-1]] if pts else []):
        print(f"  t_orig={p[0]:2d} -> t_fut={p[0]+15:2d}: ct_now={str(p[1]):5s}, ct_fut={str(p[2]):5s}, hr={str(p[3]):5s}, st={str(p[4]):5s}, w={str(p[5]):5s}")
"]}

{"argv":["python3","-c","import json
import numpy as np
from collections import defaultdict

with open('train.json') as f:
    train = json.load(f)

# Let's check what a simple function of elapsed time t_elapsed = len(history) predicts on Train 3A in LOPO CV!
# Wait: also check H04 with and without the last 4 sensor drop points (t=57..60)
train_3a_pids = ['H01', 'H03', 'H04', 'H05', 'H07', 'H10', 'H12', 'H14', 'H19']

def eval_lopo_simple():
    # For each held-out person among the 9 train_3a_pids:
    maes_raw = {}
    maes_clean = {}
    for hold_pid in train_3a_pids:
        # Fit mean ct(t_fut) as a function of t_fut on the other 13 people (excluding H04 t>=57 glitch)
        t_to_vals = defaultdict(list)
        for pid, rows in train.items():
            if pid == hold_pid:
                continue
            for i, r in enumerate(rows):
                if r['core_temp'] is not None:
                    if pid == 'H04' and i >= 56:
                        continue
                    t_to_vals[i].append(r['core_temp'])
        t_curve = {t: np.mean(v) for t, v in t_to_vals.items()}

        # Evaluate on hold_pid's 3A requests
        rows = train[hold_pid]
        fdec = next(i for i in range(1, len(rows)) if rows[i]['watts'] < rows[i-1]['watts'])
        errs_raw = []
        errs_clean = []
        for i in range(fdec, len(rows) - 15):
            target = rows[i+15]['core_temp']
            pred = t_curve[i+15]
            errs_raw.append(abs(pred - target))
            if not (hold_pid == 'H04' and i+15 >= 56):
                errs_clean.append(abs(pred - target))
        maes_raw[hold_pid] = np.mean(errs_raw)
        maes_clean[hold_pid] = np.mean(errs_clean)
    for pid in train_3a_pids:
        print(f"  {pid}: MAE_raw={maes_raw[pid]:.4f}, MAE_clean={maes_clean[pid]:.4f}")
    print(f"Mean curve only -> LOPO PB-MAE (raw): {np.mean(list(maes_raw.values())):.4f}, LOPO PB-MAE (clean): {np.mean(list(maes_clean.values())):.4f}")

eval_lopo_simple()
"]}
